// FastMediatR AOT Smoke Test
// Verifies that the FastMediatR library pipeline works when published with PublishAot=true.
//
// AOT-safe startup path (no [RequiresUnreferencedCode] calls):
//   1. FastMediatRGeneratedRegistration.Register(services) — generated by the source generator
//      at compile time, calls into zero-reflection switch-dispatch code.
//   2. Direct service registrations (no Assembly.GetTypes() / reflection-based scanning).
//
// This approach is the recommended path for AOT and fully-trimmed scenarios; it avoids
// the single reflection touchpoint in AddFastMediatR<TMarker>() (Assembly.GetType lookup).
// See usage guide §12 for guidance.
//
// Exit code: 0 = all assertions passed; non-zero = failure details written to stderr.

using FastMediatR;
using FastMediatR.Aot.SmokeTest;
using FastMediatR.Generated;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;
using Microsoft.Extensions.Options;

// ── Service registration (fully AOT-safe) ─────────────────────────────────────
var services = new ServiceCollection();

// Step 1 — Zero-reflection handler + dispatcher registration emitted by the source generator.
FastMediatRGeneratedRegistration.Register(services);

// Step 2 — Notification publisher (direct type reference, no reflection).
services.TryAddSingleton<INotificationPublisher, TaskWhenAllPublisher>();

// Step 3 — FastMediatR options (using Options.Create avoids the configuration infrastructure).
services.AddSingleton(Options.Create(new FastMediatROptions
{
    PerformanceThresholdMs = 5000,
    EnableLogging = false,
    EnablePayloadLogging = false,
}));

// ── Execute smoke test ────────────────────────────────────────────────────────
await using var provider = services.BuildServiceProvider();
var mediator = provider.GetRequiredService<IMediator>();

// 1. IRequest<TResponse> dispatch
var result = await mediator.Send(new SmokeTestCommand("hello")).ConfigureAwait(false);

if (result != "SMOKE:hello")
{
    await Console.Error.WriteLineAsync($"FAIL Send<string>: expected 'SMOKE:hello', got '{result}'").ConfigureAwait(false);
    return 1;
}

// 2. IRequest (void / Unit) dispatch
var unit = await mediator.Send(new SmokeTestVoidCommand("void-check")).ConfigureAwait(false);

if (unit != Unit.Value)
{
    await Console.Error.WriteLineAsync($"FAIL Send<Unit>: expected Unit.Value, got '{unit}'").ConfigureAwait(false);
    return 1;
}

// 3. INotification fan-out dispatch
SmokeNotificationTracker.HandlerAInvoked = false;
SmokeNotificationTracker.HandlerBInvoked = false;

await mediator.Publish(new SmokeTestNotification("ping")).ConfigureAwait(false);

if (!SmokeNotificationTracker.HandlerAInvoked)
{
    await Console.Error.WriteLineAsync("FAIL Publish: handler A was not invoked").ConfigureAwait(false);
    return 1;
}

if (!SmokeNotificationTracker.HandlerBInvoked)
{
    await Console.Error.WriteLineAsync("FAIL Publish: handler B was not invoked (fan-out broken)").ConfigureAwait(false);
    return 1;
}

// 4. ISender / IPublisher interface segregation — both interfaces must be independently
//    resolvable and functionally dispatch to the same underlying dispatcher instance.
var sender = provider.GetRequiredService<ISender>();
var publisher = provider.GetRequiredService<IPublisher>();

// Verify ISender dispatches correctly.
var senderResult = await sender.Send(new SmokeTestCommand("via-sender")).ConfigureAwait(false);

if (senderResult != "SMOKE:via-sender")
{
    await Console.Error.WriteLineAsync($"FAIL ISender dispatch: expected 'SMOKE:via-sender', got '{senderResult}'").ConfigureAwait(false);
    return 1;
}

// Verify IPublisher dispatches correctly.
SmokeNotificationTracker.HandlerAInvoked = false;
await publisher.Publish(new SmokeTestNotification("via-publisher")).ConfigureAwait(false);

if (!SmokeNotificationTracker.HandlerAInvoked)
{
    await Console.Error.WriteLineAsync("FAIL IPublisher dispatch: handler A not invoked via IPublisher").ConfigureAwait(false);
    return 1;
}

Console.WriteLine("FastMediatR AOT smoke test PASSED.");
return 0;
